)

/**
 * A crash draft: the event as reported (local date and time, place),
 * the airplane (N-number, its Mode S code where the registry gave one),
 * where it stands, and what the identity check found. `track` is "adsb",
 * or "none" for a draft of the place alone; `fatal` None where no source
 * says, which holds publishing as a fatal event does.
 */
@Serializable
data class StudioDraft (
    val aircraft: String? = null,
    val captions: StudioDraftCaptions? = null,
    val city: String? = null,
    val fatal: Boolean? = null,
    val hex: String? = null,
    val id: String,
    val identity: StudioDraftIdentity? = null,

    @SerialName("identity_by")
    val identityBy: String? = null,

    @SerialName("kit_at")
    val kitAt: Double? = null,

    val lat: Double? = null,

    @SerialName("local_date")
    val localDate: String,

    @SerialName("local_time")
    val localTime: String? = null,

    val lon: Double? = null,

    @SerialName("n_number")
    val nNumber: String? = null,

    @SerialName("noticed_at")
    val noticedAt: Double? = null,

    @SerialName("rendered_at")
    val renderedAt: Double? = null,

    val sources: List<StudioDraftSource>,
    val state: String? = null,
    val status: String,
    val track: String? = null
)

/**
 * The film's words, facts only: a title, "Preliminary ...", "No ADS-B
 * track" where there is none, the sources' words quoted, the credits.
 */
@Serializable
data class StudioDraftCaptions (
    val credits: List<String>,
    val quotes: List<StudioDraftQuote>,
    val status: String,
    val title: String,
    val track: String? = null
)

@Serializable
data class StudioDraftQuote (
    val source: String? = null,
    val url: String? = null,
    val words: String
)

/**
 * The engine's verdict on the draft's identity, each check made, the
 * window it read the track in and the report nearest the place.
 */
@Serializable
data class StudioDraftIdentity (
    val checks: List<StudioDraftCheck>,
    val nearest: StudioDraftNearest? = null,
    val verdict: String,
    val window: StudioDraftWindow? = null
)

/**
 * One of the identity check's checks (the engine's occurrence_identity).
 */
@Serializable
data class StudioDraftCheck (
    val check: String,
    val ok: Boolean,
    val words: String
)

/**
 * The track's report in the window nearest the reported place.
 */
@Serializable
data class StudioDraftNearest (
    @SerialName("distance_nm")
    val distanceNm: Double,

    val lat: Double,
    val lon: Double,
    val t: Double
)

/**
 * The time window the report gives, s since 1970 (UTC).
 */
@Serializable
data class StudioDraftWindow (
    val end: Double,
    val start: Double
)

/**
 * One source's word of the event, as it gave it: "faa_statement",
 * "faa_notice" or "ntsb"; its page (or the notice's file); its heading
 * and its words, unchanged, which a caption quotes.
 */
@Serializable
data class StudioDraftSource (
    val heading: String? = null,
    val source: String,
    val text: String? = null,
    val url: String? = null
)

/**
 * The developer's word on a draft's identity: right (`confirm`), or
 * not; with an N-number where the report gave none, which the job then
 * checks against the registry and the track as it checks its own.
 */
@Serializable
data class StudioDraftIdentityAsk (
    val confirm: Boolean,

    @SerialName("n_number")
    val nNumber: String? = null
)

/**
 * The ground's height under each point asked, ft MSL, in order: the
 * elevation tiles (USGS 3DEP and SRTM, wingtip.elevation).
 */
@Serializable
data class StudioGround (
    @SerialName("ground_ft")
    val groundFt: List<Double>
)

/**
 * Points along a replayed track, [lat, lon] each, for the ground
 * under them: the Studio's profile strip.
 */
@Serializable
data class StudioGroundAsk (
    val points: List<List<Double>>
)

/**
 * The NOTAMs and TFRs in force at a moment inside a box, from the day's
 * archive kept here (wingtip.history.notam_archive); `archived` False
 * where no archive covers that UTC day.
 */
@Serializable
data class StudioNotams (
    val archived: Boolean,
    val day: String,
    val notams: List<StudioNotam>,
    val tfrs: List<StudioTfr>
)

/**
 * A NOTAM in force then, as sent, at its field's position (None for
 * one at no field).
 */
@Serializable
data class StudioNotam (
    val end: String? = null,
    val id: String,
    val lat: Double? = null,
    val lon: Double? = null,
    val start: String? = null,
    val text: String
)

/**
 * A TFR in force then: its NOTAM's id, title, times and text, and its
 * areas (GeoJSON MultiPolygon, rounded to about 11 m).
 */
@Serializable
data class StudioTfr (
    val end: String? = null,
    val geometry: JsonObject? = null,
    val id: String,
    val name: String,
    val start: String? = null,
    val text: String? = null
)

/**
 * An airplane's reports on a UTC day, for the Studio's replay
 * (wingtip.traffic.day_tracks), with where they came from, which the
 * Studio shows (ODbL 1.0 asks for it).
 */
@Serializable
data class StudioTrack (
    val altitude: String,
    val day: String,
    val hex: String,
    val license: String,
    val model: String? = null,
    val points: List<StudioReport>,
    val registration: String? = null,
    val source: String,
    val type: String? = null
)

/**
 * One report of the day: when (s since 1970), where, its altitude
 * (ft; the transponder's pressure altitude for adsb.lol's day, see
 * `altitude`; None on the ground), ground speed (kt), track (degrees
 * true), whether it was on the ground, and the altimeter setting.
 */
@Serializable
data class StudioReport (
    @SerialName("alt_ft")
    val altFt: Double? = null,

    val ground: Boolean? = null,

    @SerialName("gs_kt")
    val gsKt: Double? = null,

    val lat: Double,
    val lon: Double,

    @SerialName("qnh_hpa")
    val qnhHpa: Double? = null,

    val t: Double,

    @SerialName("track_deg")
    val trackDeg: Double? = null
)

/**
 * An airplane followed here (its card opened), whose reports are
 * recorded (wingtip.traffic.recorded): one the Studio can replay without
 * asking adsb.lol.
 */
@Serializable
data class StudioWatched (
    val days: List<String>,
    val hex: String,
    val registration: String? = null
)

/**
 * The weather as it was over a replayed flight
 * (wingtip.history.weather_then): the METARs of the stations near its
 * track from an hour before to an hour after, the TAFs in force over it,
 * and the radar's frames, with where they came from.
 */
@Serializable
data class StudioWeather (
    val credit: String,
    val metars: List<StudioMetar>,
    val radar: List<StudioRadarFrame>,
    val source: String,
    val tafs: List<StudioTaf>
)

/**
 * A station's METAR, as it sent it (IEM's archive).
 */
@Serializable
data class StudioMetar (
    val lat: Double,
    val lon: Double,
    val raw: String,
    val station: String,
    val time: String
)

/**
 * The NEXRAD composite at one five-minute mosaic: its time and its
 * XYZ tile template on IEM's tile cache.
 */
@Serializable
data class StudioRadarFrame (
    val tiles: String,
    val valid: String
)

/**
 * A station's TAF, as the NWS issued it (IEM's archive).
 */
@Serializable
data class StudioTaf (
    val issued: String,
    val raw: String,
    val station: String
)

/**
 * A replayed flight's span (s since 1970, UTC) and points along its
 * track, [lat, lon] each, for the weather as it was.
 */
@Serializable
data class StudioWeatherAsk (
    val end: Double,
    val points: List<List<Double>>,
    val start: Double
)

@Serializable
data class Tfrs (
    val tfrs: List<Tfr>
)

/**
 * A TFR with its areas, for the map: a GeoJSON MultiPolygon.
 */
@Serializable
data class Tfr (
    @SerialName("ceiling_ft")
    val ceilingFt: Double? = null,

    @SerialName("ceiling_ref")
    val ceilingRef: String? = null,

    val effective: String? = null,
    val expires: String? = null,

    @SerialName("floor_ft")
    val floorFt: Double? = null,

    @SerialName("floor_ref")
    val floorRef: String? = null,

    val geometry: JsonObject,
    val kind: String? = null,

    @SerialName("notam_id")
    val notamId: String,

    val purpose: String? = null,
    val rule: String? = null,
    val state: String? = null,
    val title: String? = null
)

/**
 * The airplanes ADS-B receivers hear near a point, from adsb.lol's
 * open data, under the Open Database License 1.0, which asks that the
 * map say so where it draws them.
 */
@Serializable
data class Traffic (
    @SerialName("age_s")
    val ageS: Double? = null,

    val aircraft: List<TrafficAircraft>,
    val license: String? = null,
    val source: String? = null
)

/**
 * The airplanes in the air a pilot named by callsign, registration
 * or ICAO address (wingtip.traffic.find); and, where none is in the air or
 * heard now, the FAA's record of the one named (wingtip.traffic.registered),
 * to open its card all the same.
 */
@Serializable
data class TrafficFound (
    val aircraft: List<TrafficAircraft>,
    val checked: Boolean? = null,
    val license: String? = null,
    val registered: AircraftRegistration? = null,
    val source: String? = null
)

@Serializable
data class WaypointsInView (
    val waypoints: List<WaypointPin>
)

/**
 * A VFR waypoint on the sectional (VPBNG), for the map's diamond: a
 * tap names it, and with a route open puts it in the stops.
 */
@Serializable
data class WaypointPin (
    val description: String? = null,
    val ident: String,
    val lat: Double,
    val lon: Double
)

/**
 * The briefing's own parameters besides the route (GET /api/briefing):
 * the flight's minutes, and the nav log's fixes ("lat,lon;lat,lon") and
 * each leg's minutes where the page has them, for each hazard to be
 * placed where the flight meets it.
 */
@Serializable
data class WeatherAsk (
    val dep: String,
    val depart: String? = null,
    val dest: String,

    @SerialName("ete_min")
    val eteMin: Double? = null,

    val fixes: String? = null,

    @SerialName("leg_min")
    val legMin: String? = null,

    val stops: List<String>? = null
)

/**
 * The radar or satellite loop the map plays, oldest frame first, the
 * step between frames, how old the newest may be before the apps label
 * it old, and the sources' credit.
 */
@Serializable
data class WeatherLoop (
    val credit: String,
    val frames: List<LoopFrame>,
    val kind: String,

    @SerialName("old_after_s")
    val oldAfterS: Double,

    @SerialName("step_s")
    val stepS: Double
)

/**
 * One frame of the loop (wingtip.weather_loop): when it was made, ISO
 * UTC -- the older of its layers' times -- and each layer's XYZ tile
 * template, None where the frame does not draw it. The satellite's
 * carries `{bbox-epsg-3857}`, the tile's box in web Mercator metres.
 */
@Serializable
data class LoopFrame (
    @SerialName("radar_tiles")
    val radarTiles: String? = null,

    @SerialName("satellite_tiles")
    val satelliteTiles: String? = null,

    val valid: String
)

/**
 * The weather the map draws in the part of it in sight, for `at`
 * (UNIX seconds): areas, pilot reports, the winds aloft where an altitude
 * was asked for, and when the radar mosaic was made (ISO UTC).
 */
@Serializable
data class WeatherMap (
    val advisories: List<WeatherArea>? = null,
    val at: Double,
    val pireps: List<MapPirep>? = null,

    @SerialName("radar_valid")
    val radarValid: String? = null,

    val winds: MapWinds? = null
)

/**
 * An area of weather on the map (wingtip.weather_map.advisories_in): a
 * SIGMET, a convective SIGMET or a G-AIRMET snapshot; its hazard, its
 * severity where one is given, its altitudes (feet MSL; `low_ft` None
 * from the surface, or from the freezing level where
 * `from_freezing_level`), when it is valid (a G-AIRMET at `valid_from`,
 * a snapshot), its text (a SIGMET's raw report, a G-AIRMET's cause), and
 * its outline, [lat, lon] pairs.
 */
@Serializable
data class WeatherArea (
    val coords: List<List<Double>>,

    @SerialName("from_freezing_level")
    val fromFreezingLevel: Boolean? = null,

    val hazard: String? = null,

    @SerialName("high_ft")
    val highFt: Double? = null,

    val id: String,
    val kind: String,

    @SerialName("low_ft")
    val lowFt: Double? = null,

    val raw: String? = null,
    val severity: String? = null,

    @SerialName("valid_from")
    val validFrom: Double? = null,

    @SerialName("valid_to")
    val validTo: Double? = null
)

/**
 * A pilot report on the map, where it was made (wingtip.weather).
 */
@Serializable
data class MapPirep (
    val aircraft: String? = null,

    @SerialName("altitude_ft")
    val altitudeFt: Double? = null,

    val icing: String? = null,
    val lat: Double,
    val lon: Double,

    @SerialName("observed_at")
    val observedAt: String? = null,

    val raw: String? = null,
    val turbulence: String? = null,
    val urgent: Boolean? = null
)

@Serializable
data class MapWinds (
    @SerialName("altitude_ft")
    val altitudeFt: Double,

    val period: JsonObject? = null,
    val stations: List<StationWind>
)

/**
 * An FD station's forecast wind (true) and temperature at the map's
 * altitude.
 */
@Serializable
data class StationWind (
    @SerialName("dir_true_deg")
    val dirTrueDeg: Double,

    val ident: String,
    val lat: Double,
    val lon: Double,

    @SerialName("speed_kt")
    val speedKt: Double,

    @SerialName("temp_c")
    val tempC: Double? = null
)

/**
 * A reading's sources, in the order they bear on the flight; for the
 * NOTAMs, the day the NOTAM feed was first heard (`coverage_since`, ISO
 * date) and what could not be checked ("tfrs"). The feed (SWIM's FNS)
 * sends what is issued or changed once it is heard, so NOTAMs issued
 * before that day and never changed are not in the store: the list is
 * what was heard since, not every NOTAM in force (the owner, 2026-11-09,
 * chose the feed alone over the FAA NOTAM API's full load).
 */
@Serializable
data class WordsSources (
    @SerialName("coverage_since")
    val coverageSince: String? = null,

    val sources: List<WordsSource>,
    val unchecked: List<String>? = null
)

/**
 * The raw thing a sentence can rest on, as the pilot can read it: a
 * METAR or a NOTAM as sent, a TAF line, a hazard's words, a finding's
 * line, a debrief figure's line. `id` is what a sentence cites
 * ("metar:KDLH", "finding:fuel"); `label` is its heading on screen.
 */
@Serializable
data class WordsSource (
    val id: String,
    val label: String,
    val text: String
)
